pub fn getPreVarsCount(mut in_txt: Tpl::Text, mut in_a_modelInfo: SimCode::ModelInfo) -> Result<Tpl::Text> {
    let mut out_txt: Tpl::Text = <Tpl::Text as ::std::default::Default>::default();
    out_txt = (match (in_txt.clone(), in_a_modelInfo.clone()) {
        (mut txt, mut i_modelInfo @ SimCode::ModelInfo { varInfo: SimCode::VarInfo { numZeroCrossings: _, .. }, .. }) => {
            let mut ret_8: i32 = 0;
            let mut ret_7: i32 = 0;
            let mut ret_6: i32 = 0;
            let mut txt_5: Tpl::Text = <Tpl::Text as ::std::default::Default>::default();
            let mut ret_4: i32 = 0;
            let mut txt_3: Tpl::Text = <Tpl::Text as ::std::default::Default>::default();
            let mut ret_2: i32 = 0;
            let mut txt_1: Tpl::Text = <Tpl::Text as ::std::default::Default>::default();
            let mut l_allVarCount: Tpl::Text = <Tpl::Text as ::std::default::Default>::default();
            txt_1 = numRealvars(Tpl::emptyTxt.clone(), i_modelInfo.clone())?;
            ret_2 = stringInt((Tpl::textString(txt_1.clone())?).clone())?;
            txt_3 = numIntvars(Tpl::emptyTxt.clone(), i_modelInfo.clone())?;
            ret_4 = stringInt((Tpl::textString(txt_3.clone())?).clone())?;
            txt_5 = numBoolvars(Tpl::emptyTxt.clone(), i_modelInfo.clone())?;
            ret_6 = stringInt((Tpl::textString(txt_5.clone())?).clone())?;
            ret_7 = intAdd(ret_4.clone(), ret_6.clone());
            ret_8 = intAdd(ret_2.clone(), ret_7.clone());
            l_allVarCount = Tpl::writeStr(Tpl::emptyTxt.clone(), (intString(ret_8.clone())).clone())?;
            txt = Tpl::writeText(txt.clone(), l_allVarCount.clone())?;
            txt.clone()
        },
        (mut txt, _) => {
            txt.clone()
        },
    });
    Ok(out_txt)
}

